# ============================================================
#  CATALYST - Data Refresh Script
#
#  Self-contained: run from inside CATALYST_Dashboard\.
#  All paths are relative to this script's own folder.
#
#  Folder layout expected:
#    CATALYST_Dashboard\
#      Refresh_CATALYST.ps1   <- this file
#      Refresh_CATALYST.bat   <- double-click launcher
#      CATALYST.html          <- dashboard entry point
#      data.js                <- regenerated by this script
#      data\
#        Payment Integrity Inventory Model.xlsb   <- Excel source
# ============================================================

$ErrorActionPreference = "Stop"

# ── Paths (all relative to this script — fully portable) ────
$dashDir      = $PSScriptRoot
$excelFile    = Join-Path $dashDir "data\Payment Integrity Inventory Model.xlsb"
$outFile      = Join-Path $dashDir "data.js"
$catalystHtml = Join-Path $dashDir "CATALYST.html"

Write-Host ""
Write-Host "  =========================================" -ForegroundColor Cyan
Write-Host "   CATALYST Data Refresh" -ForegroundColor White
Write-Host "  =========================================" -ForegroundColor Cyan
Write-Host ""

# ── Validate Excel source ────────────────────────────────────
if (!(Test-Path $excelFile)) {
    Write-Host "  ERROR: Excel source file not found." -ForegroundColor Red
    Write-Host "  Expected: $excelFile" -ForegroundColor Yellow
    Write-Host ""
    Write-Host "  Ensure the file exists at:" -ForegroundColor White
    Write-Host "  CATALYST_Dashboard\data\Payment Integrity Inventory Model.xlsb" -ForegroundColor Cyan
    Read-Host "  Press Enter to exit"
    exit 1
}

# ── Kill any lingering Excel COM instances ──────────────────
Stop-Process -Name EXCEL -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 1

Write-Host "  Source : data\Payment Integrity Inventory Model.xlsb" -ForegroundColor Gray
Write-Host "  Output : data.js" -ForegroundColor Gray
Write-Host ""

# ── Helper: Excel OA date serial -> yyyy-MM-dd ──────────────
function ConvertExcelDate {
    param($serial)
    if ($null -eq $serial -or "$serial" -eq '') { return '' }
    try {
        return ([DateTime]::FromOADate([double]$serial)).ToString("yyyy-MM-dd")
    }
    catch { return '' }
}

# ── Open workbook ───────────────────────────────────────────
$excel = New-Object -ComObject Excel.Application
$excel.Visible       = $false
$excel.DisplayAlerts = $false

$metricsCount = 0
$slaCount     = 0
$metricsJson  = '[]'
$slaJson      = '[]'

try {
    $wb = $excel.Workbooks.Open($excelFile)

    # ── Refresh Power Query connections before reading ──────
    # The flat output sheets (Inventory_Metrics, Inventory_Summary, etc.) are
    # Power Query results. Without a refresh they may contain stale/zero values
    # for dates added to the source since the last manual refresh in Excel.
    Write-Host "  Refreshing Power Query connections..." -ForegroundColor Gray
    for ($ci = 1; $ci -le $wb.Connections.Count; $ci++) {
        try { $wb.Connections.Item($ci).OLEDBConnection.BackgroundQuery = $false } catch {}
        try { $wb.Connections.Item($ci).ODBCConnection.BackgroundQuery  = $false } catch {}
    }
    $wb.RefreshAll()
    # Wait for all async queries to complete (poll WorkbookIsRefreshing until clear)
    $maxWait = 120   # seconds
    $elapsed = 0
    while ($elapsed -lt $maxWait) {
        Start-Sleep -Seconds 2
        $elapsed += 2
        $stillBusy = $false
        for ($ci = 1; $ci -le $wb.Connections.Count; $ci++) {
            try {
                if ($wb.Connections.Item($ci).OLEDBConnection.Refreshing) { $stillBusy = $true; break }
            } catch {}
        }
        if (-not $stillBusy) { break }
    }
    Write-Host "  Power Query refresh complete ($elapsed s)." -ForegroundColor Green

    # ── Read Inventory_Metrics ──────────────────────────────
    Write-Host "  Reading Inventory_Metrics..." -ForegroundColor Gray

    $ws    = $wb.Sheets.Item("Inventory_Metrics")
    $data  = $ws.UsedRange.Value2
    $nRows = $ws.UsedRange.Rows.Count

    $metricsList = [System.Collections.Generic.List[string]]::new()

    for ($r = 2; $r -le $nRows; $r++) {
        $dateStr = ConvertExcelDate $data[$r, 1]
        if ($dateStr -eq '') { continue }

        $invType = [string]$data[$r, 2]
        $invType = $invType -replace '\\', '\\' -replace '"', '\"'

        $metric  = [string]$data[$r, 3]
        $metric  = $metric  -replace '\\', '\\' -replace '"', '\"'

        $rawVal  = $data[$r, 4]
        $numVal  = if ($null -eq $rawVal) { 0 } else { [double]$rawVal }

        $entry = '{"Date":"' + $dateStr + '","InventoryType":"' + $invType + '","Metric":"' + $metric + '","Value":' + $numVal + '}'
        $metricsList.Add($entry)
    }

    $metricsCount = $metricsList.Count
    $metricsJson  = '[' + ($metricsList -join ',') + ']'
    Write-Host "  Inventory_Metrics : $metricsCount rows" -ForegroundColor Green

    # ── Read Enterprise SLA from Inventory_Summary ─────────────
    # Source: Inventory_Summary sheet
    #   Row 3 = date header row (Excel OA date serials, starting col 5)
    #   Row 2 = Enterprise-wide SLA % for each date (the TOP yellow SLA
    #           row visible on the Summary tab, Index=1, no Section/Metric)
    # This is the ONLY correct source for the dashboard Enterprise SLA KPI.
    # Inventory_SLA sheet contains per-type SLA (COB only) and must NOT
    # be used for the enterprise-level metric.
    Write-Host "  Reading Enterprise SLA from Inventory_Summary (Row 2 / Row 3)..." -ForegroundColor Gray

    $wsSummary = $wb.Sheets.Item("Inventory_Summary")
    $nColsSummary = $wsSummary.UsedRange.Columns.Count

    $slaList = [System.Collections.Generic.List[string]]::new()

    # Col 5 onward: row 3 = OA date serial, row 2 = enterprise SLA %
    for ($c = 5; $c -le $nColsSummary; $c++) {
        $serial = $wsSummary.Cells.Item(3, $c).Value2   # date serial in row 3
        $slaRaw = $wsSummary.Cells.Item(2, $c).Value2   # enterprise SLA in row 2

        if ($null -eq $serial -or "$serial" -eq '') { continue }

        $dateSerial = 0.0
        if (-not [double]::TryParse("$serial", [ref]$dateSerial)) { continue }
        if ($dateSerial -lt 40000) { continue }   # skip non-date values

        $dateStr = ([DateTime]::FromOADate($dateSerial)).ToString("yyyy-MM-dd")

        $slaD = 0.0
        if ($null -eq $slaRaw -or -not [double]::TryParse("$slaRaw", [ref]$slaD)) { continue }
        # Skip placeholder zeros and out-of-range values
        if ($slaD -le 0 -or $slaD -gt 1) { continue }

        $slaPct = [Math]::Round($slaD, 6)
        $entry  = '{"Date":"' + $dateStr + '","SLA_Pct":' + $slaPct + '}'
        $slaList.Add($entry)
    }

    $slaCount = $slaList.Count
    $slaJson  = '[' + ($slaList -join ',') + ']'
    Write-Host "  Enterprise SLA    : $slaCount rows (from Inventory_Summary)" -ForegroundColor Green

    $wb.Close($false)
}
catch {
    Write-Host ""
    Write-Host "  ERROR reading Excel: $_" -ForegroundColor Red
    try { $excel.Quit() } catch {}
    try { [System.Runtime.InteropServices.Marshal]::ReleaseComObject($excel) | Out-Null } catch {}
    Read-Host "  Press Enter to exit"
    exit 1
}
finally {
    try { $excel.Quit() } catch {}
    try { [System.Runtime.InteropServices.Marshal]::ReleaseComObject($excel) | Out-Null } catch {}
}

# ── Validate row counts ─────────────────────────────────────
if ($metricsCount -eq 0 -or $slaCount -eq 0) {
    Write-Host ""
    Write-Host "  ERROR: No data returned from Excel." -ForegroundColor Red
    Write-Host "  Inventory_Metrics: $metricsCount rows | Inventory_SLA: $slaCount rows" -ForegroundColor Yellow
    Read-Host "  Press Enter to exit"
    exit 1
}

# ── Write data.js (no here-strings — CRLF, UTF-8 no BOM) ───
Write-Host ""
Write-Host "  Writing data.js..." -ForegroundColor Gray

$refreshTime = Get-Date -Format "yyyy-MM-dd HH:mm:ss"

$lines = [System.Collections.Generic.List[string]]::new()
$lines.Add('/* ============================================================')
$lines.Add('   CATALYST - Embedded Data')
$lines.Add('   Generated : ' + $refreshTime)
$lines.Add('   Inventory_Metrics : ' + $metricsCount + ' rows')
$lines.Add('   Inventory_SLA     : ' + $slaCount + ' rows')
$lines.Add('   DO NOT EDIT - regenerated by Refresh_CATALYST.ps1')
$lines.Add('   ============================================================ */')
$lines.Add('')
$lines.Add('window.CATALYST_DATA = {')
$lines.Add('  metrics: ' + $metricsJson + ',')
$lines.Add('  sla:     ' + $slaJson)
$lines.Add('};')

$outputText = $lines -join "`r`n"
$utf8NoBom  = [System.Text.UTF8Encoding]::new($false)
[System.IO.File]::WriteAllText($outFile, $outputText, $utf8NoBom)

$sizeMB = [Math]::Round((Get-Item $outFile).Length / 1MB, 2)

# ── Success summary ─────────────────────────────────────────
Write-Host ""
Write-Host "  =========================================" -ForegroundColor Cyan
Write-Host "   CATALYST Refresh Successful" -ForegroundColor Green
Write-Host "  =========================================" -ForegroundColor Cyan
Write-Host "  Inventory_Metrics rows : $metricsCount" -ForegroundColor White
Write-Host "  Inventory_SLA rows     : $slaCount" -ForegroundColor White
Write-Host "  data.js size           : $sizeMB MB" -ForegroundColor White
Write-Host "  data.js updated        : $refreshTime" -ForegroundColor White
Write-Host "  =========================================" -ForegroundColor Cyan
Write-Host ""

# ── Auto-open dashboard ─────────────────────────────────────
$open = Read-Host "  Open CATALYST.html now? [Y/N]"
if ($open -match '^[Yy]') {
    Start-Process $catalystHtml
}
